import { Routes, Route, Navigate } from "react-router-dom";
import Home from "../../pages/Home";
import Login from "../../pages/Login";
import DashboardEmotes from "../../pages/DashboardEmotes";
import NotFound from "../../pages/NotFound";
import useAuth from "../../hooks/useAuth";
import PrivateRoute from "../components/PrivateRoute";
import GuestRoute from "../components/GuestRoute";
import Terms from "../../pages/Terms";
import EmotesGlobal from "../../pages/EmotesGlobal";
import EmotesShared from "../../pages/EmotesShared";
import EmotesTop from "../../pages/EmotesTop";
import Emote from "../../pages/Emote";
import User from "../../pages/User";
import DashboardPaint from "../../pages/DashboardPaint";
import DashboardSub from "../../pages/DashboardSub";
import DashboardEditor from "../../pages/DashboardEditor";
import Privacy from "../../pages/Privacy";

function AppRoutes() {
  const auth = useAuth();

  return auth ? (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/terms" element={<Terms />} />
      <Route path="/privacy" element={<Privacy />} />
      <Route path="/emotes/global" element={<EmotesGlobal />} />
      <Route path="/emotes/shared" element={<EmotesShared />} />
      <Route path="/emotes/top" element={<EmotesTop />} />
      <Route path="/emotes/:id" element={<Emote />} />
      <Route path="/users/:id" element={<User />} />
      <Route
        path="/dashboard/paint"
        element={
          <PrivateRoute>
            <DashboardPaint />
          </PrivateRoute>
        }
      />
      <Route
        path="/dashboard/emotes"
        element={
          <PrivateRoute>
            <DashboardEmotes />
          </PrivateRoute>
        }
      />
      <Route
        path="/dashboard/sub-badges"
        element={
          <PrivateRoute>
            <DashboardSub />
          </PrivateRoute>
        }
      />
      <Route
        path="/dashboard/editors"
        element={
          <PrivateRoute>
            <DashboardEditor />
          </PrivateRoute>
        }
      />
      <Route
        path="/login"
        element={
          <GuestRoute>
            <Login />
          </GuestRoute>
        }
      />
      <Route path="/logout" element={<Navigate to="/" />} />

      <Route path="*" element={<NotFound />} />
    </Routes>
  ) : (
    <div> loading </div>
  );
}

export default AppRoutes;
