import React from "react";
import { Nav } from "react-bootstrap";
import useAuth from "../../../hooks/useAuth";

const NavbarDashboard = (props) => {
  const auth = useAuth();

  return (
    <Nav variant="tabs" defaultActiveKey={props.defaultActiveKey}>
      <Nav.Link href="#/dashboard/emotes">Эмоции</Nav.Link>
      {auth.editor === null && <br></br>}
      {auth.editor === null && <br></br>}
      {auth.editor === null && (
        <Nav.Link href="#/dashboard/paint">Цвет имени</Nav.Link>
      )}
      <br></br>
      <br></br>
      <Nav.Link href="#/dashboard/sub-badges">Значок подписчика</Nav.Link>
      {auth.editor === null && <br></br>}
      {auth.editor === null && <br></br>}
      {auth.editor === null && (
        <Nav.Link href="#/dashboard/editors">Редакторы</Nav.Link>
      )}
    </Nav>
  );
};

export default NavbarDashboard;
