import React from "react";
import ButtonLoading from "../ButtonLoading/ButtonLoading";

const EditorUser = (props) => {
  if (props.loading) {
    return (
      <div className="div_user skelet-loading">
        <div>
          <img
            width={34}
            height={34}
            src="data:image/gif;base64,"
            alt="profile"
            className="loading"
          />
          <div
            style={{ width: "90px", height: "16px", marginLeft: "5px" }}
            className="loading"
          ></div>
        </div>
        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "flex-end",
            marginRight: "5px",
          }}
        >
          <div
            style={{ height: "24px", width: "24px" }}
            className="loading"
          ></div>
        </div>
      </div>
    );
  }

  return (
    <div className="div_user flat-btn ovg">
      <div style={{ marginRight: "auto" }}>
        <img
          width={34}
          height={34}
          src={
            props.user.editor?.channel_image || props.user.user?.channel_image
          }
          alt="avatar"
        />
        <span>
          {props.user.editor?.user_login || props.user.user?.user_login}
        </span>
      </div>
      {typeof props.isLoadingRemove !== "undefined" && (
        <button
          onClick={() =>
            props.deleteEditor(
              props.user.editor?.user_id || props.user.user?.user_id
            )
          }
          disabled={
            props.isLoadingRemove ===
            (props.user.editor?.user_id || props.user.user?.user_id)
          }
          className="warning small ovg"
          style={{ width: "24px", marginRight: "5px" }}
        >
          {props.isLoadingRemove ===
          (props.user.editor?.user_id || props.user.user?.user_id) ? (
            <ButtonLoading />
          ) : (
            "x"
          )}
        </button>
      )}
    </div>
  );
};

export default EditorUser;
