import React from "react";
import { Link } from "react-router-dom";
import { decode } from "../../../lib/code-mnem";
import { HOSTURL } from "../../../index.js";
import classnames from "classnames";

const Emotes = (props) => {
  if (props.loading) {
    return (
      <div
        className={classnames(
          "div_emoteCard",
          "skelet-loading",
          props.showUsername && "user"
        )}
      >
        <div className="emoteCard">
          <img
            style={{ minWidth: "50px" }}
            src="data:image/gif;base64,"
            alt="loading"
            className="loading"
          />
          <div>
            <span className="loading-after"></span>
            {props.showUsername && <span className="loading-after"></span>}
          </div>
        </div>
      </div>
    );
  }

  const encoded = decode(props.emote.code);

  return (
    <div className={classnames("div_emoteCard", props.showUsername && "user")}>
      <Link
        to={"/emotes/" + props.emote._id}
        className="emoteCard"
        title={encoded}
      >
        <img
          src={HOSTURL + "/cached/emote/" + props.emote._id + "/2x"}
          alt={encoded}
        />
        <div>
          <span>{encoded}</span>
          {props.showUsername && <span>{props.emote.user?.user_login}</span>}
          {!!props.emote.visibility_simple?.filter((t) => t === "ZERO_WIDTH")
            .length && <div> &gt; &lt; </div>}
        </div>
      </Link>
    </div>
  );
};

export default Emotes;
