import React from "react";
import { Nav } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import DropdownButton from "react-bootstrap/DropdownButton";
import Dropdown from "react-bootstrap/Dropdown";
import useAuth from "../../../hooks/useAuth";

const Navbar = (props) => {
  const auth = useAuth();
  const navigate = useNavigate();

  const onLogOut = () => {
    auth.logOut();
    navigate("/");
  };

  const toEditor = (profile) => {
    auth.setEditor({
      profile_image: profile.user.channel_image,
      user_id: profile.user.user_id,
      user_login: profile.user.user_login,
    });
  };

  return (
    <header>
      <Nav variant="tabs" defaultActiveKey={props.defaultActiveKey}>
        <div className="d-flex" style={{ alignItems: "flex-end" }}>
          <Nav.Link href="#/">
            <img
              alt="BWASD"
              src="https://raw.githubusercontent.com/ovgamesdev/BetterWASD.data/d14e632c63580b2628abeb7f4159311c2399d37d/Wasd_Better_color_logo_dark.svg"
            />
          </Nav.Link>
          <Nav.Link href="#/emotes/top" className="item item-link">
            эмоции
          </Nav.Link>
          {auth.user ? (
            <Nav.Link href="#/dashboard/emotes" className="item item-link">
              панель управления
            </Nav.Link>
          ) : (
            ""
          )}
          {/* <Nav.Link href="#/paint" className="item item-link">цвет имени</Nav.Link> */}
          {/* <Nav.Link href="#/help" className="item item-link">помощь</Nav.Link> */}
        </div>
        <div className="d-flex" style={{ alignItems: "flex-end" }}>
          {auth.user ? (
            <div
              className="item item-link nav-link d-flex"
              style={{ top: "15px", position: "relative" }}
            >
              {auth.user.user_role && (
                <div className="user-role">{auth.user.user_role}</div>
              )}
              <div
                className="avatar"
                style={{
                  backgroundImage: `url(${
                    auth.editor?.profile_image || auth.user.profile_image
                  })`,
                }}
              ></div>
              <DropdownButton
                id="dropdown-basic-button"
                title={auth.editor?.user_login || auth.user?.user_login}
                className="user_login"
              >
                {auth.user.channel_editor &&
                  auth.user.channel_editor.map(
                    (editor, index) =>
                      editor?.user_id !== auth.editor?.user_id && (
                        <Dropdown.Item
                          key={index}
                          onClick={() => toEditor(editor)}
                        >
                          <div
                            className="avatar-editor"
                            style={{
                              backgroundImage: `url(${editor.user?.channel_image})`,
                            }}
                          ></div>
                          {editor.user?.user_login}
                        </Dropdown.Item>
                      )
                  )}
                {auth.editor !== null && (
                  <Dropdown.Item onClick={() => auth.setEditor(null)}>
                    <div
                      className="avatar-editor"
                      style={{
                        backgroundImage: `url(${auth.user.profile_image})`,
                      }}
                    ></div>
                    {auth.user.user_login}
                  </Dropdown.Item>
                )}
                {(auth.user.channel_editor.length !== 0 || auth.editor) && (
                  <Dropdown.Divider />
                )}
                <Dropdown.Item href="#/logout" onClick={onLogOut}>
                  <svg
                    aria-hidden="true"
                    focusable="false"
                    data-prefix="fas"
                    role="img"
                    xmlns="http://www.w3.org/2000/svg"
                    viewBox="0 0 512 512"
                  >
                    <path
                      fill="currentColor"
                      d="M497 273L329 441c-15 15-41 4.5-41-17v-96H152c-13.3 0-24-10.7-24-24v-96c0-13.3 10.7-24 24-24h136V88c0-21.4 25.9-32 41-17l168 168c9.3 9.4 9.3 24.6 0 34zM192 436v-40c0-6.6-5.4-12-12-12H96c-17.7 0-32-14.3-32-32V160c0-17.7 14.3-32 32-32h84c6.6 0 12-5.4 12-12V76c0-6.6-5.4-12-12-12H96c-53 0-96 43-96 96v192c0 53 43 96 96 96h84c6.6 0 12-5.4 12-12z"
                    ></path>
                  </svg>
                  Выйти
                </Dropdown.Item>
              </DropdownButton>
            </div>
          ) : (
            <Nav.Link href="#/login" className="item item-link d-flex login">
              <svg
                aria-hidden="true"
                focusable="false"
                data-prefix="fas"
                role="img"
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 512 512"
              >
                <path
                  fill="currentColor"
                  d="M416 448h-84c-6.6 0-12-5.4-12-12v-40c0-6.6 5.4-12 12-12h84c17.7 0 32-14.3 32-32V160c0-17.7-14.3-32-32-32h-84c-6.6 0-12-5.4-12-12V76c0-6.6 5.4-12 12-12h84c53 0 96 43 96 96v192c0 53-43 96-96 96zm-47-201L201 79c-15-15-41-4.5-41 17v96H24c-13.3 0-24 10.7-24 24v96c0 13.3 10.7 24 24 24h136v96c0 21.5 26 32 41 17l168-168c9.3-9.4 9.3-24.6 0-34z"
                ></path>
              </svg>
              login
            </Nav.Link>
          )}
        </div>
      </Nav>
    </header>
  );
};

export default Navbar;
